/*
 * prog54_topo_sort
 *
 * The original binary implements a very small topological‑sort utility.
 * It expects at most 7 vertices and at most 7 edges (the original
 * program checks that both numbers are < 8).  The command line format
 * is:
 *
 *     prog54_topo_sort N M u1 v1 u2 v2 ... uM vM
 *
 * where the vertices are numbered 0 … N‑1.  If the input is malformed
 * the program prints "INVALID_INPUT".  If the directed graph contains a
 * cycle it prints "CYCLE".  Otherwise it prints a topological ordering
 * of the vertices, separated by a single space and terminated by a
 * newline.
 *
 * The implementation below follows the same logic as the state‑machine
 * observed in the disassembly, but is written in clear C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8          /* the original binary allows vertices < 8 */
#define MAXE 8          /* the original binary allows edges    < 8 */

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
     *  Input validation – the original program checks:
     *      * N and M are non‑negative integers
     *      * N < 8 and M < 8
     *      * the number of arguments matches 3 + 2*M
     *  If any test fails it prints "INVALID_INPUT" and exits with 1.
     * ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 1;
    }

    long N = strtol(argv[1], NULL, 10);
    long M = strtol(argv[2], NULL, 10);

    if (N < 0 || M < 0 || N >= MAXV || M >= MAXE) {
        puts("INVALID_INPUT");
        return 1;
    }

    if (argc != 3 + 2 * M) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* -----------------------------------------------------------------
     *  Build adjacency matrix and indegree array.
     *  The original binary uses an 8×8 matrix of ints (adj) and an
     *  indegree array of 8 ints.  It also keeps a "done" array to mark
     *  vertices that have already been output.
     * ----------------------------------------------------------------- */
    int adj[MAXV][MAXV] = {0};
    int indegree[MAXV] = {0};
    bool done[MAXV] = {false};

    for (long i = 0; i < M; ++i) {
        long u = strtol(argv[3 + 2 * i], NULL, 10);
        long v = strtol(argv[4 + 2 * i], NULL, 10);

        /* The original code does not perform explicit range checks
         * for u and v; out‑of‑range values would corrupt memory.
         * To stay faithful we simply ignore such edges – the
         * behaviour is undefined in the original, but this keeps the
         * program safe. */
        if (u < 0 || u >= N || v < 0 || v >= N)
            continue;

        adj[u][v] = 1;
        indegree[v] += 1;
    }

    /* -----------------------------------------------------------------
     *  Kahn's algorithm for topological sorting.
     *  The state machine in the binary repeatedly:
     *      * finds a vertex with indegree 0 that is not yet done,
     *      * marks it done, stores it in the output array,
     *      * decrements indegree of all its outgoing neighbours.
     *  If at some iteration no such vertex exists while not all vertices
     *  are done, a cycle is reported.
     * ----------------------------------------------------------------- */
    int order[MAXV];
    int out_len = 0;

    while (out_len < N) {
        int v = -1;
        for (int i = 0; i < N; ++i) {
            if (!done[i] && indegree[i] == 0) {
                v = i;
                break;
            }
        }

        if (v == -1) {                 /* no vertex with indegree 0 */
            puts("CYCLE");
            return 1;
        }

        done[v] = true;
        order[out_len++] = v;

        for (int w = 0; w < N; ++w) {
            if (adj[v][w]) {
                indegree[w]--;
            }
        }
    }

    /* -----------------------------------------------------------------
     *  Output the ordering: numbers separated by a single space,
     *  terminated by a newline.
     * ----------------------------------------------------------------- */
    for (int i = 0; i < out_len; ++i) {
        if (i) putchar(' ');
        printf("%d", order[i]);
    }
    putchar('\n');

    return 0;
}
